CREATE TABLE `guided_storefront_profiles` (`workspace_id` text PRIMARY KEY NOT NULL,`business_type` text NOT NULL,`brand_name` text NOT NULL,`tagline` text NOT NULL,`accent_color` text NOT NULL,`featured_product_ids_json` text DEFAULT '[]' NOT NULL,`featured_collection_ids_json` text DEFAULT '[]' NOT NULL,`desired_content_json` text DEFAULT '[]' NOT NULL,`completeness_json` text DEFAULT '{}' NOT NULL,`generated_at` integer NOT NULL,`updated_at` integer NOT NULL,FOREIGN KEY (`workspace_id`) REFERENCES `workspaces`(`id`));
